contract InvMutTest {
    C c;
    constructor(C _c) payable { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        // fund c by sending Ether to it directly (C has no receive, but this contract is the deployer; use a plain transfer)
        // Instead: fund via low-level call is disallowed; c can only be funded if it had balance. Check pre-funding:
        // C has no payable fallback, so sending to address(c) fails; therefore c's balance is always 0 here.
        // Rule: sendTo to address(c) (a contract with no receive/fallback) reverts, and C's balance stays the same.
        uint balBefore = address(c).balance;
        bool reverted;
        c.sendTo(address(c), amount);
        reverted = false;
        assert(!(reverted) || address(c).balance == balBefore);
    }
    receive() external payable {}
}

