contract InvMutTest {
    C c;
    bool rejectTransfer;

    constructor(C _c) { c = _c; }

    function run(uint amount, bool reject) public payable {
        require(amount > 0);
        require(address(this).balance > 0);

        rejectTransfer = reject;

        uint cBefore = address(c).balance;
        uint rBefore = address(this).balance;

        bool reverted;
        try c.sendTo(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reject) {
            assert(reverted && address(c).balance == cBefore && address(this).balance == rBefore);
        } else {
            assert(!reverted && address(this).balance == rBefore + amount && address(c).balance == cBefore);
        }
    }

    receive() external payable {
        require(!rejectTransfer);
    }
}

