    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // fund c so it has at least `amount`
        c.sendTo(address(this), amount);
        // after first send, c holds `amount` (this contract received it)
        // send it back to this contract from c
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        c.sendTo(address(this), amount);
        assert(address(this).balance == thisBalBefore + amount && address(c).balance == cBalBefore - amount);
    }
    receive() external payable {}
